import zipfile
import xml.etree.ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'

with zipfile.ZipFile('budget.xlsx') as z:
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rid_to_target = {rel.get('Id'): rel.get('Target') for rel in rels}

    shared_strings = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall(f'{{{M}}}si'):
            shared_strings.append(''.join(t.text or '' for t in si.iter(f'{{{M}}}t')))

    for sheet in wb.find(f'{{{M}}}sheets'):
        name = sheet.get('name')
        rid = sheet.get(f'{{{R}}}id')
        target = rid_to_target[rid]
        if target.startswith('/'):
            path = target.lstrip('/')
        elif not target.startswith('xl/'):
            path = 'xl/' + target
        else:
            path = target
        print(f"=== Sheet {name!r} ({path}) ===")
        ws = ET.fromstring(z.read(path))
        for row in ws.iter(f'{{{M}}}row'):
            vals = []
            for c in row:
                ref = c.get('r')
                t = c.get('t')
                v = c.find(f'{{{M}}}v')
                raw = v.text if v is not None else None
                if t == 's' and raw is not None:
                    val = shared_strings[int(raw)]
                elif t == 'inlineStr':
                    val = ''.join(x.text or '' for x in c.iter(f'{{{M}}}t'))
                else:
                    val = raw
                vals.append(f"{ref}={val}")
            if vals:
                print(" | ".join(vals))

